changeSet.sql:
CREATE TABLE branch ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, name TEXT NOT NULL, address TEXT, phone TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE role ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE users ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, branch_id UUID REFERENCES branch(id), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE user_role ( user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id UUID NOT NULL REFERENCES role(id) ON DELETE CASCADE, PRIMARY KEY (user_id, role_id) );
CREATE TABLE customer ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, name TEXT NOT NULL, phone TEXT, address TEXT, cpf_cnpj TEXT, branch_id UUID NOT NULL REFERENCES branch(id), created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE book ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, title TEXT NOT NULL, author TEXT NOT NULL, isbn TEXT, publisher TEXT, year INTEGER, category TEXT, condition TEXT NOT NULL, condition_description TEXT, sale_price NUMERIC(10,2) NOT NULL, description TEXT, branch_id UUID NOT NULL REFERENCES branch(id), shelf_location TEXT, registered_at TIMESTAMP NOT NULL DEFAULT now(), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE book_image ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, book_id UUID NOT NULL REFERENCES book(id) ON DELETE CASCADE, url TEXT NOT NULL, "order" INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE book_stock ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, book_id UUID NOT NULL REFERENCES book(id) ON DELETE CASCADE, branch_id UUID NOT NULL REFERENCES branch(id), quantity INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT now(), UNIQUE (book_id, branch_id) );
CREATE TABLE price_history ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, book_id UUID NOT NULL REFERENCES book(id) ON DELETE CASCADE, previous_price NUMERIC(10,2) NOT NULL, new_price NUMERIC(10,2) NOT NULL, changed_by UUID NOT NULL REFERENCES users(id), changed_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE label_config ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, branch_id UUID REFERENCES branch(id), name TEXT NOT NULL, width_cm NUMERIC(5,2) NOT NULL, height_cm NUMERIC(5,2) NOT NULL, is_default BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE discount ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch(id), scope TEXT NOT NULL, value_type TEXT NOT NULL, value NUMERIC(10,2) NOT NULL, category TEXT, author TEXT, min_price NUMERIC(10,2), max_price NUMERIC(10,2), starts_at TIMESTAMP, ends_at TIMESTAMP, active BOOLEAN NOT NULL DEFAULT TRUE, created_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE discount_book ( discount_id UUID NOT NULL REFERENCES discount(id) ON DELETE CASCADE, book_id UUID NOT NULL REFERENCES book(id) ON DELETE CASCADE, PRIMARY KEY (discount_id, book_id) );
CREATE TABLE payment_method ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch(id), name TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE voucher ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch(id), customer_id UUID NOT NULL REFERENCES customer(id), initial_value NUMERIC(10,2) NOT NULL, remaining_balance NUMERIC(10,2) NOT NULL, issued_by UUID NOT NULL REFERENCES users(id), issued_at TIMESTAMP NOT NULL DEFAULT now(), active BOOLEAN NOT NULL DEFAULT TRUE );
CREATE TABLE sale ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch(id), cashier_id UUID NOT NULL REFERENCES users(id), customer_id UUID REFERENCES customer(id), total_amount NUMERIC(10,2) NOT NULL, discount_amount NUMERIC(10,2) NOT NULL DEFAULT 0, receipt_printed BOOLEAN NOT NULL DEFAULT FALSE, sold_at TIMESTAMP NOT NULL DEFAULT now(), created_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE sale_item ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, sale_id UUID NOT NULL REFERENCES sale(id) ON DELETE CASCADE, book_id UUID NOT NULL REFERENCES book(id), unit_price NUMERIC(10,2) NOT NULL, discounted_price NUMERIC(10,2) NOT NULL, quantity INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE sale_payment ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, sale_id UUID NOT NULL REFERENCES sale(id) ON DELETE CASCADE, payment_method_id UUID NOT NULL REFERENCES payment_method(id), amount NUMERIC(10,2) NOT NULL, voucher_id UUID REFERENCES voucher(id) );
CREATE TABLE voucher_usage ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, voucher_id UUID NOT NULL REFERENCES voucher(id), sale_id UUID NOT NULL REFERENCES sale(id), amount_used NUMERIC(10,2) NOT NULL, used_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE used_book_purchase ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch(id), total_price NUMERIC(10,2) NOT NULL, payment_method TEXT NOT NULL, seller_name TEXT, purchased_by UUID NOT NULL REFERENCES users(id), purchased_at TIMESTAMP NOT NULL DEFAULT now(), notes TEXT );
CREATE TABLE used_book_purchase_item ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, purchase_id UUID NOT NULL REFERENCES used_book_purchase(id) ON DELETE CASCADE, book_id UUID NOT NULL REFERENCES book(id) );
CREATE TABLE customer_wishlist ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, customer_id UUID NOT NULL REFERENCES customer(id) ON DELETE CASCADE, branch_id UUID NOT NULL REFERENCES branch(id), title TEXT NOT NULL, author TEXT, isbn TEXT, notified BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE shelf_threshold ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch(id) UNIQUE, days_threshold INTEGER NOT NULL, configured_by UUID NOT NULL REFERENCES users(id), updated_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE TABLE notification ( id UUID NOT NULL DEFAULT uuidv7() PRIMARY KEY, branch_id UUID NOT NULL REFERENCES branch(id), user_id UUID NOT NULL REFERENCES users(id), type TEXT NOT NULL, message TEXT NOT NULL, book_id UUID REFERENCES book(id), customer_wishlist_id UUID REFERENCES customer_wishlist(id), read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT now() );
CREATE INDEX idx_book_branch ON book(branch_id); CREATE INDEX idx_book_isbn ON book(isbn); CREATE INDEX idx_book_title ON book(title); CREATE INDEX idx_book_author ON book(author); CREATE INDEX idx_notification_user ON notification(user_id, read); CREATE INDEX idx_voucher_customer ON voucher(customer_id, active); CREATE INDEX idx_price_history_book ON price_history(book_id, changed_at DESC); CREATE INDEX idx_wishlist_customer ON customer_wishlist(customer_id);
INSERT INTO role (id, name, description, created_at, updated_at) VALUES (uuidv7(), 'Administrador', 'Acesso total ao sistema', now(), now()), (uuidv7(), 'Gerente', 'Gestão da própria filial', now(), now()), (uuidv7(), 'Catalogador', 'Cadastro e edição de livros', now(), now()), (uuidv7(), 'Caixa', 'Operação do PDV', now(), now());
